 \label{prop:bilinear-freq-concentration}
Let $c, a \in \mathbb{Z}_+$, $1 \ll M, N \ll c$, and $I, J \subset \mathbb{Z}$ be nonempty discrete intervals of lengths $|I| = M$, $|J| = N$. Let $(a_m)_{m \in I}, (b_n)_{n \in J}$ be complex sequences, and $\mu, \nu$ be bounded-variation complex Borel measures on $\mathbb{R}/\mathbb{Z}$, such that $\check{\mu}(m) = a_m$ for $m \in I$ and $\check{\nu}(n) = b_n$ for $n \in J$. Then for any $\varepsilon > 0$, one has
\begin{equation} \label{eq:bilinear-freq-concentration}
    \sum_{m \in I} a_m \sum_{n \in J} b_n\, S(am, an; c) 
    \ll_\varepsilon c^\varepsilon
    \iint_{(\mathbb{R}/\mathbb{Z})^2} \left(c\, T_{M,N}(\alpha, \beta) + \gcd(a, c) MN\right) d|\mu|(\alpha)\, d|\nu|(\beta),
\end{equation}
By \cref{eq:tn-bound}, when $M = N$, this bound is $\ll c^\varepsilon (cN^{2/3} + \gcd(a, c) N^2)\, |\mu|(\mathbb{R}/\mathbb{Z})\, |\nu|(\mathbb{R}/\mathbb{Z})$.

\begin{equation} \label{eq:bilinear-freq-concentration}
    \sum_{m \in I} a_m \sum_{n \in J} b_n\, S(am, an; c) 
    \ll_\varepsilon c^\varepsilon
    \iint_{(\mathbb{R}/\mathbb{Z})^2} \left(c\, T_{M,N}(\alpha, \beta) + \gcd(a, c) MN\right) d|\mu|(\alpha)\, d|\nu|(\beta),
\end{equation}

\begin{equation} \label{eq:b-split}
    \widehat{b_i}(\alpha) = \widehat{c_i}(\ell_i \alpha - \alpha_i),
\end{equation}

\begin{equation} \label{eq:a-fourier-bound}
    \widehat{a}(\alpha) 
    \ll 
    \begin{cases}
        H^2, & \max\left(\|\ell_1 \alpha - \alpha_1\|, \|\ell_2 \alpha - \alpha_2\|\right) \le H^{\varepsilon-1}, \\
        O_\varepsilon(H^{-100}), & \max\left(\|\ell_1 \alpha - \alpha_1\|, \|\ell_2 \alpha - \alpha_2\|\right) > H^{\varepsilon-1},
    \end{cases}
\end{equation}

\begin{equation} \label{eq:m-pair}
    \ell_1 m_2 - \ell_2 m_1 = \ell_2\alpha_1 - \ell_1 \alpha_2
     + O\left(H^{\varepsilon-1} \frac{L}{\ell_0}\right).
\end{equation}

\[
    \left\{\alpha \in \mathbb{R}/\mathbb{Z} : \max\left(\|\ell_1 \alpha - \alpha_1\|, \|\ell_2 \alpha - \alpha_2\|\right) \le H^{\varepsilon-1} \right\}
\]

\[
\begin{aligned}
    \|\widehat{a}\|_{L^p} &\ll_\varepsilon H^{O(\varepsilon)} \left(H^{2p} \left(H^{-1} L^{-1} + H^{-2}\right) + 1\right)^{\frac{1}{p}}
    \\
    &\ll_p H^{O(\varepsilon)} \left(H^{2-\frac{2}{p}} + \frac{H^{2-\frac{1}{p}}}{L^{\frac{1}{p}}}\right),
\end{aligned}
\]

\begin{equation} \label{eq:I-bound-1}
    \mathcal{I}_N(\mu) \ll \iint_{(\mathbb{R}/\mathbb{Z})^2} \min \left(\sqrt{N(1 + \|\alpha-\beta\| N)}, N^{2/3} \right)\,
        d|\mu|(\alpha)\, d|\mu|(\beta),
\end{equation}

\begin{equation} \label{eq:I-bound-2}
    |\mu|(\mathbb{R}/\mathbb{Z})^2 \ll \mathcal{I}_N(\mu) \ll 
    N^{2/3} |\mu|(\mathbb{R}/\mathbb{Z})^2.
\end{equation}

 \label{thm:large-sieve-freq-concentration}
Let $\varepsilon > 0$, $X, A > 0$, $N \ge 1/2$, $q, a \in \mathbb{Z}_+$, and $(a_n)_{n \sim N}$ be a complex sequence. Let $f : (0, 4) \to \mathbb{C}$ be a smooth function with $f^{(j)} \ll_j 1$ for $j \ge 0$, and $\mu$ be a bounded-variation complex Borel measure on $\mathbb{R}/\mathbb{Z}$, such that\footnote{We slightly abuse notation in this section: the measure $\mu$ should not be confused with the cusp parameter $\mu(\mathfrak{a}) = q^{-1}$, and the scalar $a$ should not be confused with the sequence $(a_n)$.}
\[
    a_n = f\left(\frac{n}{N}\right) \check{\mu}\left(n\right),
\]
for all $n \sim N$ (in particular, one can take $f \equiv 1$, $d\mu = \widehat{a}\, d\lambda$). Let $\mathfrak{a}, \rho_{j\mathfrak{a}}(n), \lambda_j,\theta_j$ be as in \cref{thm:large-sieve-general}, with $\mu(\mathfrak{a}) = q^{-1}$ and the choice of scaling matrix $\sigma_{\mathfrak{a}}$ in \cref{eq:scaling-choices}. Then one has
\begin{equation} \label{eq:large-sieve-freq-concentration}
    \sum_{\lambda_j < 1/4}
    X^{\theta_j} 
    \left\vert 
    \sum_{n \sim N} a_n\, \rho_{j\mathfrak{a}}(an)
    \right\vert^2 
    \ll_\varepsilon 
    (qaNX)^{2\varepsilon}
    \left(1 + \frac{aN}{q}\right) A^2,
\end{equation}
whenever
\begin{equation} \label{eq:X-freq-concentration}
    A \gg \|a_n\|_2 + \frac{\sqrt{\gcd(a, q)} N}{\sqrt{q+aN}} |\mu|(\mathbb{R}/\mathbb{Z}),
    \qquad\qquad
    X \ll \max\left(1, \frac{q}{aN}\right) \max\left(1, \frac{A^2}{\mathcal{I}_N(\mu)}\right).
\end{equation}

\begin{equation} \label{eq:large-sieve-freq-concentration}
    \sum_{\lambda_j < 1/4}
    X^{\theta_j} 
    \left\vert 
    \sum_{n \sim N} a_n\, \rho_{j\mathfrak{a}}(an)
    \right\vert^2 
    \ll_\varepsilon 
    (qaNX)^{2\varepsilon}
    \left(1 + \frac{aN}{q}\right) A^2,
\end{equation}

\begin{equation} \label{eq:X-freq-concentration}
    A \gg \|a_n\|_2 + \frac{\sqrt{\gcd(a, q)} N}{\sqrt{q+aN}} |\mu|(\mathbb{R}/\mathbb{Z}),
    \qquad\qquad
    X \ll \max\left(1, \frac{q}{aN}\right) \max\left(1, \frac{A^2}{\mathcal{I}_N(\mu)}\right).
\end{equation}

\begin{equation} \label{eq:some-freq-concentration}
    |\mu|(\mathbb{R}/\mathbb{Z}) 
    \ll 
    (qN)^{o(1)} \frac{\sqrt{q+aN}}{N} \|a_n\|_2
    \qquad\quad 
    \text{and}
    \qquad\quad
    \mathcal{I}_N(\mu) = o\left(\|a_n\|_2^2\right).
\end{equation}

\begin{equation} \label{eq:mu-lower-bound}
    |\mu|(\mathbb{R}/\mathbb{Z}) \gg N^{-1/2}\, \|a_n\|_2,
\end{equation}

\begin{equation} \label{eq:to-show-large-sieve}
    \mathcal{S} := \sum_{c \in \mathcal{C}_{\mathfrak{a}\mathfrak{a}}} \frac{1}{c} 
    \sum_{m,n \sim N} \overline{a_m}\, a_n\, S_{\mathfrak{a} \mathfrak{a}}(am, an; c)\, \Phi\left(\frac{\sqrt{mn}}{c} X \right)
    \ll_\varepsilon 
    (qaNX)^{2\varepsilon} \left(1 + \frac{aN}{q}\right) A^2,
\end{equation}

\begin{equation} \label{eq:S-split}
    \mathcal{S} = \sum_{\substack{c \in (aNX/4, aNX) \\ c \equiv 0 \pmod{q} \\ }} \frac{\mathcal{S}(c)}{c},
\end{equation}

\begin{equation} \label{eq:wlog-conc}
    \mathcal{I}_N(\mu) \ll A^2.
\end{equation}

\begin{equation} \label{eq:sc-again}
    \mathcal{S}(c) = \sum_{m,n \sim N} \overline{\check{\mu}(m)} \, \check{\mu}(n)\, S(am, an; c)\, \Psi_c\left(\frac{m}{N}, \frac{n}{N}\right),
\end{equation}

\begin{equation} \label{eq:Sc-split}
    \mathcal{S}(c) = \iint_{\mathbb{R}^2} \widehat{\Psi_c}(t_1, t_2)\, \mathcal{S}(c, t_1, t_2)\, dt_1\, dt_2,
\end{equation}

\begin{equation} \label{eq:final-s-bound}
    \mathcal{S} \ll_\varepsilon (aNX)^{2\varepsilon} \left(\frac{aNX}{q} \mathcal{I}_{N} (\mu) + \frac{\gcd(a, q) N^2}{q} |\mu|(\mathbb{R}/\mathbb{Z})^2 \right).
\end{equation}

\[
    X \ll \max\left(1, \frac{q}{aN}\right) \frac{N}{\min_{t \in \mathbb{Z}_+} \left(t + N\|t\alpha\|\right)}
\]

\begin{equation} \label{eq:mu-total-mass}
    |\mu|(\mathbb{R}/\mathbb{Z}) = \|\varphi\|_{L^1} \ll_\varepsilon H^\varepsilon \left(1 + \frac{H}{L}\right).
\end{equation}

\begin{equation} \label{eq:In-total-mass}
\begin{aligned}
    \mathcal{I}_{N}(\mu) 
    =
    \iint_{(\mathbb{R}/\mathbb{Z})^2} T_{N}(\alpha, \beta)\, d|\mu|(\alpha)\, d|\mu|(\beta) 
    &\ll_{\varepsilon}
    L H^{-90}
    +
    H^\varepsilon L M\, |\mu|(\mathbb{R}/\mathbb{Z})^2
    \\
    &\ll_{\varepsilon} 
    H^{2\varepsilon} L M\left(1 + \frac{H}{L}\right)^2.
\end{aligned}
\end{equation}

 \label{ass:large-sieve}
This applies to complex sequences $(a_n)_{n \sim N}$ and parameters $q \in \mathbb{Z}_+$, $N \ge 1/2$, $Z \gg 1$, $A_N \gg \|a_n\|_2$, $Y_N > 0$. For any $\varepsilon > 0, \xi \in \mathbb{R}$, any cusp $\mathfrak{a}$ of $\Gamma_0(q)$ with $\mu(\mathfrak{a}) = q^{-1}$ and $\sigma_{\mathfrak{a}}$ chosen as in \cref{eq:scaling-choices}, and any orthonormal basis of Maass cusp forms for $\Gamma_0(q)$, with eigenvalues $\lambda_j$ and Fourier coefficients $\rho_{j\mathfrak{a}}(n)$, one has
\begin{equation} \label{eq:large-sieve-rephrased}
    \sum_{\lambda_j < 1/4} X^{\theta_j} \left\vert \sum_{n \sim N} e\left(\frac{n}{N} \xi \right) a_n\, \rho_{j\mathfrak{a}}(n) \right\vert^2 
    \ll_\varepsilon
    (qNZ)^\varepsilon 
    \left(1 + \frac{N}{q}\right) 
     A_N^2,
\end{equation}
for all $X \ll \max\left(1, \frac{q}{N}\right) \frac{Y_N}{1+|\xi|^2}$. Here, $\theta_j := \sqrt{1-4\lambda_j}$ and $\theta(q) := \max_{\lambda_j < 1/4} \theta_j(q)$.

\begin{equation} \label{eq:sequence-choice-1}
    a_n := e(n\alpha), \qquad\qquad Y_N := \frac{N}{T_N(\alpha)} \gg \sqrt{N},
    \qquad\qquad A_N := \sqrt{N},
\end{equation}

\begin{equation} \label{eq:sequence-choice-2}
\begin{gathered}
    a_n := 
    \sum_{\substack{h_1, h_2 \in \mathbb{Z} \\ h_1\ell_1 - h_2\ell_2 = n}} \Phi_1\left(\frac{h_1}{H}\right) \Phi_2\left(\frac{h_2}{H}\right) e(h_1\alpha_1 + h_2\alpha_2),
    \\
    Y_N := \max\left(1, \frac{NH}{(H+L)L \min_i T_H(\alpha_i)}\right) 
    ,
    \qquad
    A_N := \|a_n\|_2 + \sqrt{N}\sqrt{\frac{H}{L} + \frac{H^2}{L^2}},
\end{gathered}
\end{equation}

 \label{cor:kloosterman-averaging-nc}
Let $(q, N, Z, (a_n)_{n \sim N}, Y_N, A_N)$ satisfy \cref{ass:large-sieve}. Let $\varepsilon > 0$, $C \gg 1$, $m \in \mathbb{Z}_+$, and $\mathfrak{a}, \mathfrak{b}$ be cusps of $\Gamma_0(q)$, with $\mu(\mathfrak{a}) = \mu(\mathfrak{b}) = q^{-1}$ and $\sigma_{\mathfrak{b}}$ as in \cref{eq:scaling-choices}. Let $\Phi : (0, \infty)^2 \to \mathbb{C}$ be a smooth function, with $\Phi(x, y)$ supported in $x, y \asymp 1$, and $\partial_x^j \partial_y^k \Phi(x, y) \ll_{j,k,\varepsilon} Z^{j\varepsilon}$ for $j, k \ge 0$. Then with a consistent choice of the $\pm$ sign, one has
\begin{equation} \label{eq:kloosterman-nc}
\begin{aligned}
    \sum_{n \sim N} a_n
    \sum_{c \in \mathcal{C}_{\mathfrak{a}\mathfrak{b}}} \Phi\left(\frac{n}{N}, \frac{c}{C}\right) S_{\mathfrak{a}\mathfrak{b}}(m, \pm n; c)
    \ll_\varepsilon
    (qmNCZ)^{O(\varepsilon)}
    \left(1 + T\right)^{\theta(q)}
    \frac{C^2 A_N}{C + \sqrt{mN}} 
    \\
    \times 
    \left(1 + \frac{mN}{C^2} +\frac{\sqrt{(q,m)m}}{q} \right)^{1/2}
    \left(1 + \frac{mN}{C^2} + \frac{N}{q}\right)^{1/2}
    ,
\end{aligned}
\end{equation}
for
\[
    T = \frac{T_0}{\sqrt{Y_N}}, 
    \qquad\qquad 
    T_0 := \frac{C}{\max\left(m, q^2 (q, m)^{-1} \right)^{1/2}\max\left(N, q\right)^{1/2}}
    \le
    \frac{C}{q^{3/2} (q,m)^{-1/2}}.
\]

\begin{equation} \label{eq:kloosterman-nc}
\begin{aligned}
    \sum_{n \sim N} a_n
    \sum_{c \in \mathcal{C}_{\mathfrak{a}\mathfrak{b}}} \Phi\left(\frac{n}{N}, \frac{c}{C}\right) S_{\mathfrak{a}\mathfrak{b}}(m, \pm n; c)
    \ll_\varepsilon
    (qmNCZ)^{O(\varepsilon)}
    \left(1 + T\right)^{\theta(q)}
    \frac{C^2 A_N}{C + \sqrt{mN}} 
    \\
    \times 
    \left(1 + \frac{mN}{C^2} +\frac{\sqrt{(q,m)m}}{q} \right)^{1/2}
    \left(1 + \frac{mN}{C^2} + \frac{N}{q}\right)^{1/2}
    ,
\end{aligned}
\end{equation}

Denote by $\mathcal{S}$ the sum in \cref{eq:kloosterman-nc}. 
Letting $\Psi(x; y) := \sqrt{x}\, \Phi(x, \sqrt{x}/y)$, we can Fourier expand
\[
    \sqrt{x}\, \Phi\left(x, \frac{\sqrt{x}}{y} \right) = \int_{\mathbb{R}} \widehat{\Psi}(\xi; y) \, e(x\xi)\, d\xi,
\]
where the Fourier transform is taken in the first variable. Integrating by parts in $x$, we note that for $k \ge 0$,
\[
    \partial_y^k\, \widehat{\Psi}(\xi; y) \ll_{j,\varepsilon} \frac{Z^{O(\varepsilon)}}{1 + \xi^4},
\]
where the implied constant in $O(\varepsilon)$ (say, $K > 0$) does not depend on $k$. Then we can let
\[
    \varphi_{\xi}(y) := Z^{-K\varepsilon}\, \left(1 + \xi^4 \right) \widehat{\Psi}\left(\xi; y \frac{C}{4\pi \sqrt{mN}} \right) \frac{4\pi \sqrt{mN}}{C y},
\]
which is supported in $y \asymp X^{-1}$ and satisfies $\varphi_\xi^{(k)} \ll_{k,\varepsilon} X^k$, for
\begin{equation} \label{eq:X-CmN}
    X := \frac{C}{\sqrt{mN}}.
\end{equation}
This way, we can rewrite
\[
\begin{aligned}
    \Phi\left(\frac{n}{N}, \frac{c}{C}\right)
    &=
    \int_{\mathbb{R}} \sqrt{\frac{N}{n}} \widehat{\Psi}\left(\xi; \frac{C}{c} \sqrt{\frac{n}{N}}\right) e\left(\frac{n}{N} \xi \right)\, d\xi
    \\
    &=
    Z^{K\varepsilon} \frac{C}{c}
    \int_{\mathbb{R}} \frac{1}{1 + \xi^4} e\left(\frac{n}{N} \xi \right) \varphi_\xi\left(\frac{4\pi \sqrt{mn}}{c}\right) d\xi,
\end{aligned}
\]
and thus
\begin{equation} \label{eq:S-split-xi}
    \mathcal{S} \ll_\varepsilon Z^{O(\varepsilon)} C \int_{\mathbb{R}} \frac{|S(\xi)|\, d\xi}{1+\xi^4}, 
\end{equation}
where
\[
    \mathcal{S}(\xi) := \sum_{n \sim N} e\left(\frac{n}{N} \xi\right) a_n
    \sum_{c \in \mathcal{C}_{\mathfrak{a}\mathfrak{b}}}\,
    \frac{\mathcal{S}_{\mathfrak{a}\mathfrak{b}}(m, \pm n; c)}{c} 
    \varphi_\xi\left(\frac{4\pi \sqrt{mn}}{c}\right).
\]
The inner sum is in a suitable form to apply the Kuznetsov trace formula from \cref{prop:kuznetsov}. We only show the case when the choice of the $\pm$ sign is positive; the negative case is analogous (and in fact simpler due to the lack of holomorphic cusp forms). The resulting contribution of the Maass cusp forms to $\mathcal{S}(\xi)$ is
\[
\begin{aligned}
    \mathcal{S}_{\mathcal{M}}(\xi) 
    &\ll \sum_{j=1}^\infty \frac{|\widehat{\mathcal{B}}_{\varphi_\xi}(\kappa_j)|}{\cosh(\pi \kappa_j)} 
    |\rho_{j\mathfrak{a}}(m)| \left\vert \sum_{n \sim N} e\left(\frac{n}{N} \xi\right) a_n\,  
    \rho_{j\mathfrak{b}}(n)\right\vert
    =:
    \mathcal{S}_{\mathcal{M},\text{exc}}(\xi) + \mathcal{S}_{\mathcal{M},\text{reg}}(\xi),
\end{aligned}
\]
where $\mathcal{S}_{\mathcal{M},\text{exc}}$ contains the terms with $\lambda_j < 1/4$ and $\mathcal{S}_{\mathcal{M},\text{reg}}$ contains the rest.
We first bound $\mathcal{S}_{\mathcal{M},\text{reg}}$; the contribution of the holomorphic cusp forms and Eisenstein series is bounded analogously. For the Bessel transforms, we apply \cref{eq:bessel-bound-2} if $|r| \le R$ and \cref{eq:bessel-bound-3} otherwise, where $R \ge 1$ will be chosen shortly. Together with Cauchy--Schwarz and the bounds in \cref{lem:coefficient-bounds} (in $m$) and \cref{lem:large-sieve-non-exceptional} (in $n \sim N$), this yields
\[
\begin{aligned}
    \mathcal{S}_{\mathcal{M},\text{reg}}(\xi)
    \ll_\varepsilon (qmNR)^\varepsilon 
    &\left(\frac{1 + |\log X|}{1 + X^{-1}} + R^{-5/2} + R^{-3} X^{-1}\right) 
    \\
    &\times \left(R^2 + \frac{\sqrt{(q,m)m}}{q}\right)^{1/2} \left(R^2 + \frac{N}{q}\right)^{1/2} \|a_n\|_2.
\end{aligned}
\]
Picking $R := 1 + X^{-1}$, we get
\begin{equation} \label{eq:S-bound-regular}
    \mathcal{S}_{\mathcal{M},\text{reg}}(\xi)
    \ll_\varepsilon (qmNC)^{O(\varepsilon)} \frac{1}{1 + X^{-1}}
    \left(1 + X^{-2} + \frac{\sqrt{(q,m)m}}{q}\right)^{1/2} \left(1 + X^{-2} + \frac{N}{q}\right)^{1/2} \|a_n\|_2.
\end{equation}

For the exceptional spectrum, we let $X = X_0 \sqrt{X_1 X_2}$ for $X_1, X_2 \gg 1$ to be chosen shortly, and note the bound
\[
    1 + X^{\theta_j} \ll (1 + X_0)^{\theta_j} X_1^{\theta_j/2} X_2^{\theta_j/2} 
    \ll 
    (1 + X_0)^{\theta(q)} X_1^{\theta_j/2} X_2^{\theta_j/2}.
\]
Then by \cref{eq:bessel-bound-1} and Cauchy--Schwarz, we obtain
\begin{equation} \label{eq:exceptional-contribution}
\begin{aligned}
    \mathcal{S}_{\mathcal{M},\text{exc}}(\xi)
    &\ll 
    \frac{1}{1+X^{-1}}
    \sum_{j=1}^\infty \frac{1 + X^{\theta_j}}{\cosh(\pi \kappa_j)} 
    |\rho_{j\mathfrak{a}}(m)| \left\vert \sum_{n \sim N} e\left(\frac{n}{N} \xi\right) a_n\, 
    \rho_{j\mathfrak{b}}(n)\right\vert
    \\
    &\ll
    \frac{(1 + X_0)^{\theta(q)}}{1+X^{-1}}
    \left(
    \sum_{j=1}^\infty X_1^{\theta_j} 
    |\rho_{j\mathfrak{a}}(m)|^2 \right)^{1/2}
    \left( 
    \sum_{j=1}^\infty X_2^{\theta_j} \left\vert \sum_{n \sim N} e\left(\frac{n}{N} \xi\right) a_n\,  
    \rho_{j\mathfrak{b}}(n)\right\vert^2 \right)^{1/2}.
\end{aligned}
\end{equation}
We pick $X_1$ and $X_2$ as large as \cref{eq:coefficient-bound-exceptional} and \cref{ass:large-sieve} allow, specifically
\begin{equation} \label{eq:X12}
    X_1 := \max\left(1, \frac{q^2}{(q,m) m}\right),
    \qquad\qquad 
    X_2(\xi) := \max\left(1, \frac{q}{N}\right) \frac{Y_N}{1 + |\xi|^2}.
\end{equation}
Then by \cref{lem:coefficient-bounds} and \cref{ass:large-sieve}, we obtain
\begin{equation} \label{eq:S-bound-exceptional}
    \mathcal{S}_{\mathcal{M},\text{exc}}(\xi)
    \ll_\varepsilon 
    (qmNC)^{O(\varepsilon)}
    \left(1 + \frac{X}{\sqrt{X_1 X_2(\xi)}} \right)^{\theta(q)}
    \frac{1}{1+X^{-1}} \left(1 + \frac{\sqrt{(q,m)m}}{q} \right)^{1/2}
    \left(1 + \frac{N}{q}\right)^{1/2} A_N.
\end{equation}

Putting together \cref{eq:S-bound-regular} (and the identical bounds for Eisenstein series and holomorphic cusp forms) with \cref{eq:S-bound-exceptional} and \cref{eq:S-split-xi}, while noting that $\|a_n\|_2 \ll A_N$ by \cref{ass:large-sieve}, we conclude that
\begin{equation} \label{eq:S-final-bound}
\begin{aligned}
    \mathcal{S} \ll_\varepsilon (qmNCZ)^{O(\varepsilon)}
    &\left(1 + \frac{X}{\sqrt{X_1 X_2(0)}} \right)^{\theta(q)}
    \frac{C}{1+X^{-1}} 
    \\
    &\times 
    \left(1 + X^{-2} +\frac{\sqrt{(q,m)m}}{q} \right)^{1/2}
    \left(1 + X^{-2} + \frac{N}{q}\right)^{1/2} A_N,
\end{aligned}
\end{equation}
where the factor of $1 + |\xi|^2$ inside $X_2(\xi)$ disappeared in the integral over $\xi$ with a greater decay.
This recovers the desired bound after plugging in the values of $X, X_1, X_2$ from \cref{eq:X-CmN,eq:X12}.

\begin{equation} \label{eq:X-CmN}
    X := \frac{C}{\sqrt{mN}}.
\end{equation}

\begin{equation} \label{eq:S-split-xi}
    \mathcal{S} \ll_\varepsilon Z^{O(\varepsilon)} C \int_{\mathbb{R}} \frac{|S(\xi)|\, d\xi}{1+\xi^4}, 
\end{equation}

\[
\begin{aligned}
    \mathcal{S}_{\mathcal{M}}(\xi) 
    &\ll \sum_{j=1}^\infty \frac{|\widehat{\mathcal{B}}_{\varphi_\xi}(\kappa_j)|}{\cosh(\pi \kappa_j)} 
    |\rho_{j\mathfrak{a}}(m)| \left\vert \sum_{n \sim N} e\left(\frac{n}{N} \xi\right) a_n\,  
    \rho_{j\mathfrak{b}}(n)\right\vert
    =:
    \mathcal{S}_{\mathcal{M},\text{exc}}(\xi) + \mathcal{S}_{\mathcal{M},\text{reg}}(\xi),
\end{aligned}
\]

\begin{equation} \label{eq:S-bound-regular}
    \mathcal{S}_{\mathcal{M},\text{reg}}(\xi)
    \ll_\varepsilon (qmNC)^{O(\varepsilon)} \frac{1}{1 + X^{-1}}
    \left(1 + X^{-2} + \frac{\sqrt{(q,m)m}}{q}\right)^{1/2} \left(1 + X^{-2} + \frac{N}{q}\right)^{1/2} \|a_n\|_2.
\end{equation}

\begin{equation} \label{eq:exceptional-contribution}
\begin{aligned}
    \mathcal{S}_{\mathcal{M},\text{exc}}(\xi)
    &\ll 
    \frac{1}{1+X^{-1}}
    \sum_{j=1}^\infty \frac{1 + X^{\theta_j}}{\cosh(\pi \kappa_j)} 
    |\rho_{j\mathfrak{a}}(m)| \left\vert \sum_{n \sim N} e\left(\frac{n}{N} \xi\right) a_n\, 
    \rho_{j\mathfrak{b}}(n)\right\vert
    \\
    &\ll
    \frac{(1 + X_0)^{\theta(q)}}{1+X^{-1}}
    \left(
    \sum_{j=1}^\infty X_1^{\theta_j} 
    |\rho_{j\mathfrak{a}}(m)|^2 \right)^{1/2}
    \left( 
    \sum_{j=1}^\infty X_2^{\theta_j} \left\vert \sum_{n \sim N} e\left(\frac{n}{N} \xi\right) a_n\,  
    \rho_{j\mathfrak{b}}(n)\right\vert^2 \right)^{1/2}.
\end{aligned}
\end{equation}

\begin{equation} \label{eq:X12}
