\begin{equation} \label{eq:remaining-range-1}
    x^{\alpha - 1 + \varepsilon} \ll_\varepsilon N \ll_\varepsilon \min\left( x^{2(\alpha-1)+\varepsilon}, x^{(4-3\alpha)/3 - \varepsilon}\right)
\end{equation}

\begin{equation} \label{eq:remaining-range-2}
    \min \left( x^{\alpha-1+\varepsilon}, x^{(4-(3+\theta)\alpha)/(3-4\theta)-\varepsilon} \right)
    \ll_\varepsilon N 
    \ll_\varepsilon 
    x^{(4-3\alpha)/3 - \varepsilon},
\end{equation}

This is a refinement of Merikoski's \cite[Prop.\,4.(i)]{merikoski2023largest}, using \cref{cor:kloosterman-averaging-mnc} (plus \cref{thm:large-sieve-dispersion-coeffs}) instead of Deshouillers--Iwaniec's bound \cite[Theorem 9]{deshouillers1982kloosterman}. 

We very briefly recall the relevant parts of Merikoski's argument and the sizes of the parameters therein, pointing the reader to \cite[\S 3]{merikoski2023largest} for details. In \cite[\S 3.4]{merikoski2023largest}, one expanded and Fourier-completed $|\mathcal{A}_{mn}|$, resulting in a sum over $1 \le |h| \le H$ with
\begin{equation} \label{eq:H-value}
    H := P x^{-1+\delta},
\end{equation}
as before. Then, one removed the smooth cross-conditions in $h, m, n$, and separated $k = (m, n)$ to reach the type-II sums $\Sigma_k(M, N)$ from the first display on \cite[p.\,1275]{merikoski2023largest}; we need to bound these by $\ll_\varepsilon x^{1-\delta}/k$, for $\delta = \delta(\varepsilon)$ to be chosen. 

In \cite[\S 3.5]{merikoski2023largest}, one applied Cauchy--Schwarz keeping the sums over $h, n$ inside, to obtain 
\begin{equation} \label{eq:sigma-k-cauchy}
    \Sigma_k(M, N) \ll \left(\frac{M}{k}\right)^{1/2} \Xi_k(M, N)^{1/2},
\end{equation}
and trivially bounded the contribution of $h_2 n_1 = h_1 n_2$ to $\Xi_k$, using the condition $N \gg_\varepsilon x^{\alpha-1+\varepsilon}$; then they separated $n_0 = (n_1, n_2)$ (and let $n_i \gets n_i/n_0$). We note that considering nontrivial values of the GCD-parameters $k$ and $n_0$ was not necessary in the proof of \cref{prop:type-II}.$(ii)$, since then $(b_n)$ was supported on primes; in a first pass the reader can pretend that $k = n_0 = 1$.

In \cite[\S 3.6]{merikoski2023largest}, one expanded the condition $(m, n_0n_1n_2) = 1$ by M\"obius inversion, resulting in a sum over $d \mid n_0 n_1 n_2$ (we switched notation from $\delta$ to $d$). Then, one applied Gauss' lemma (\cite[Lemma 9]{merikoski2023largest}), resulting in sums $\Psi_k(R, S)$ of incomplete Kloosterman sums, ranging over $r, s$ of sizes 
\begin{equation} \label{eq:RS-values}
    1 \ll R, S \ll \sqrt{\frac{P N}{k n_0}}.
\end{equation}
In \cite[\S 3.7]{merikoski2023largest}, one completed Kloosterman sums, resulting in a sum over $|t| \le T$ with
\begin{equation} \label{eq:T-value}
    T = x^{\delta} \frac{Sd N^2}{Rn_0},
\end{equation}
and trivially bounded the contribution of $t = 0$. This ultimately leads to the sums of Kloosterman sums $\widetilde{\Psi}_k(R, S)$
from \cite[p.\,1279]{merikoski2023largest}, which have a relevant \emph{level} of
\begin{equation} \label{eq:rho-value}
    \varrho := dk^2 n_0 n_1 n_2 \asymp \frac{dN^2}{n_0}.
\end{equation}
Finally, in \cite[\S 3.8]{merikoski2023largest}, Merikoski used \cite[Theorem 9]{deshouillers1982greatest} to bound the trilinear sums of Kloosterman sums
\[
    \mathcal{K} = \mathcal{K}(d, n_0, n_1, n_2) := \max_{\alpha \pmod{\varrho}} \left\vert 
    \sum_{m \sim \mathcal{M}} a_m \sum_{n \sim \mathcal{N}} b_n \sum_{(c, \varrho) = 1} \Phi\left(\frac{m}{\mathcal{M}}, \frac{n}{\mathcal{N}}, \frac{c}{\mathcal{C}}\right) S\left(m \overline{\varrho}, \pm n; c\right) \right\vert,
\]
where $\Phi$ is a smooth function as in \cref{cor:kloosterman-averaging-mnc} with $Z = 1$, $(c_h)$ are bounded coefficients,
\begin{equation} \label{eq:am-bn-jori}
    a_m := e\left(-m\frac{\alpha}{\varrho}\right),
    \qquad\qquad 
    b_n := \sum_{\substack{h_1 \sim H_1 \\ h_2 \sim H_2 \\ n = h_1 n_2 - h_2 n_1}} c_{h_1} \overline{c_{h_2}},
\end{equation}
both of which depend on the level $\varrho$, 
\begin{equation} \label{eq:jori-mn-bounds}
    \mathcal{M} \ll T, \qquad\qquad 
    \mathcal{N} \ll \frac{HN}{kn_0}, 
    \qquad\qquad 
    \mathcal{C} \ll S,
\end{equation}
and $1/2 \le H_2 \le H_1 \le H$.
We will achieve better bounds for $\mathcal{K}$ by leveraging the structure of the coefficients $(a_m)$ and $(b_n)$. To do so, we note that the coefficients $c_h$ (obtained by removing the cross-condition in $h, m, n$ on \cite[p.\,1274]{merikoski2023largest}) are smooth functions of $h$. In fact, expanding $|\mathcal{A}_{mn}| - \frac{\rho(mn)}{mn}$ via \cref{lem:truncated-poisson} and fixing $j, u$ up to a logarithmic loss, we can use the coefficients
\[
    c_h := \Psi_j\left(\frac{|h|}{H_j}\right) e\left(-h\frac{ux}{P}\right),
\]
from \cref{eq:h-coeffs-poisson}, where $1 \le 2^j = H_j \le H = P x^{-1+\delta}$, $u \asymp 1$, and $\Psi_j : (\frac{1}{2}, 2) \to \mathbb{C}$ are compactly-supported smooth functions with bounded derivatives. In particular, through \cref{lem:truncated-poisson} we put $|h|$ in (smooth) dyadic ranges, and then separate into positive and negative values of $h$, all before applying Cauchy--Schwarz; so the resulting variables $h_1, h_2$ are of the same size. The coefficients $(b_n)$ from \cref{eq:am-bn-jori} become
\[
    b_n := \sum_{\substack{h_1, h_2 \in \mathbb{Z} \\ n = h_1 n_2 - h_2 n_1}} c_{h_1} \overline{c_{h_2}},
\]
which are in a suitable form to use \cref{thm:large-sieve-dispersion-coeffs} (see also \cref{eq:sequence-choice-2}), with $a = 1$, $H = H_j$, $\alpha_i = \pm ux/P \ll x^\delta H^{-1}$, and 
\begin{equation} \label{eq:L-value}
    L := \frac{N}{k n_0} \asymp n_1 \asymp n_2.
\end{equation}
In particular, since $\varrho \ge n_1 n_2 \asymp L^2$, the tuple $(\varrho, \mathcal{N}, x, (b_n)_{n \sim \mathcal{N}}, A_{\mathcal{N}}, Y_{\mathcal{N}})$ satisfies \cref{ass:large-sieve} with
\begin{equation} \label{eq:jori-savings-n}
    Y_{\mathcal{N}} := \max\left(1, \frac{\mathcal{N} H_j}{(H_j+L)L x^\delta} \right)
    \qquad\quad 
    \text{and}
    \qquad\quad
    A_{\mathcal{N}} := \|b_n \mathbbm{1}_{n \sim \mathcal{N}}\|_2 + \sqrt{\mathcal{N}}\sqrt{\frac{H_j}{L} + \frac{H_j^2}{L^2}},
\end{equation}
where we used that $T_{\mathcal{N}/L}(\alpha_i) \ll T_H(\alpha_i) \ll 1 + H |\alpha_i| \ll x^\delta$. On the other hand, by \cref{thm:large-sieve-expo-phases} (see also \cref{eq:sequence-choice-1}), the tuple $(\varrho, \mathcal{M}, x, (a_m)_{m \sim \mathcal{M}}, A_{\mathcal{M}}, Y_{\mathcal{M}})$ satisfies \cref{ass:large-sieve}, with
\begin{equation} \label{eq:jori-savings-m}
    Y_{\mathcal{M}} := \sqrt{\mathcal{M}} 
    \qquad\quad 
    \text{and}
    \qquad\quad
    A_{\mathcal{M}} := \sqrt{\mathcal{M}}.
\end{equation}
By \cref{cor:kloosterman-averaging-mnc}, specifically \cref{eq:kloosterman-mnc-explicit}, it follows that
\[
    \mathcal{K} \ll_\delta x^{O(\delta)} 
    \left(1 + \frac{\mathcal{C}}{\sqrt{\varrho Y_{\mathcal{M}} Y_{\mathcal{N}}}} \right)^\theta
    A_{\mathcal{M}} A_{\mathcal{N}}
    \frac{\left(\sqrt{\varrho}\mathcal{C} + \sqrt{\mathcal{M}\mathcal{N}} + \sqrt{\mathcal{M}} \mathcal{C}\right)\left(\sqrt{\varrho}\mathcal{C} + \sqrt{\mathcal{M} \mathcal{N}} + \sqrt{\mathcal{N}} \mathcal{C}\right)}{\sqrt{\varrho}\mathcal{C} + \sqrt{\mathcal{M} \mathcal{N}}},
\]
and substituting \cref{eq:jori-savings-m,eq:jori-savings-n} gives
\begin{equation} \label{eq:jori-K-bound}
\begin{aligned}
    \mathcal{K} \ll_\delta x^{O(\delta)}
    \left(1 + \frac{\mathcal{C}}{\sqrt{\varrho} \mathcal{M}^{1/4} \max\left(1, \sqrt{\frac{\mathcal{N} H_j}{(H_j+L)L}}\right)} \right)^\theta
    \sqrt{\mathcal{M}} \left(\|b_n \mathbbm{1}_{n \sim \mathcal{N}}\|_2 + \sqrt{\mathcal{N}} \sqrt{\frac{H_j}{L} + \frac{H_j^2}{L^2}}\right)
    \\
    \times
    \frac{\left(\sqrt{\varrho}\mathcal{C} + \sqrt{\mathcal{M}\mathcal{N}} + \sqrt{\mathcal{M}} \mathcal{C}\right)\left(\sqrt{\varrho}\mathcal{C} + \sqrt{\mathcal{M} \mathcal{N}} + \sqrt{\mathcal{N}} \mathcal{C}\right)}{\sqrt{\varrho}\mathcal{C} + \sqrt{\mathcal{M} \mathcal{N}}}.
\end{aligned}
\end{equation}
Since $\mathcal{N} \ll \varrho$ (which follows from $H \ll N$), the term on the second line of \cref{eq:jori-K-bound} is at most $\ll \sqrt{\rho} \mathcal{C} + \sqrt{\mathcal{M}} \mathcal{C} + \sqrt{\mathcal{M} \mathcal{N}}$, as in \cite[p.\,1280]{merikoski2023largest}. The resulting bound is non-decreasing in $\mathcal{M}, \mathcal{C}$, so we can plug in their upper bounds from \cref{eq:jori-mn-bounds}, as well as \cref{eq:T-value,eq:rho-value} to obtain
\[
\begin{aligned}
    \sum_{d \mid n_0 n_1 n_2}
    \frac{1}{TH^2} \mathcal{K}(d, n_0, n_1, n_2)
    \ll_\delta 
    x^{O(\delta)}
    \max_{d \ge 1}
    \frac{Rn_0}{SdN^2 H^2}
    \left(1 + \frac{S \min\left(1, \sqrt{\frac{(H_j+L)L}{\mathcal{N} H_j}}\right)}{\sqrt{\frac{dN^2}{n_0}} \left(\frac{SdN^2}{Rn_0}\right)^{1/4} } \right)^\theta
    \\ 
    \times
    \sqrt{\frac{SdN^2}{Rn_0}} 
    \left(\|b_n \mathbbm{1}_{n \sim \mathcal{N}}\|_2 + \sqrt{\mathcal{N}} \sqrt{\frac{H_j}{L} + \frac{H_j^2}{L^2}}\right)
    \\
    \times 
    \left(\sqrt{\frac{dN^2}{n_0}} S + \sqrt{\frac{SdN^2}{Rn_0}} S + \sqrt{\frac{SdN^2}{Rn_0}\mathcal{N}}\right),
\end{aligned}
\]
where none of the remaining variables have implicit dependencies on $d$. The right-hand side is seen to be non-increasing in $d$, so we can plug in $d = 1$ for an upper bound. Moreover, when summing over $n_1, n_2 \sim L = N/(kn_0)$, we have the same bound as in \cite[bottom of p.\,1280]{merikoski2023largest} (by \cite[Lemma 7]{merikoski2023largest}) for the contribution of $A_{\mathcal{N}}$:
\[
    \sum_{n_1, n_2 \sim L} \left(\|b_n \mathbbm{1}_{n \sim \mathcal{N}}\|_2 + \sqrt{\mathcal{N}} \sqrt{\frac{H_j}{L} + \frac{H_j^2}{L^2}} \right) 
    \ll 
    \sqrt{\mathcal{N}} \max\left(H_jL, H_j^{1/2} L^{3/2}\right).
\]
The resulting bound for $\sum_{n_1, n_2 \sim L} \sum_{d \mid n_0 n_1 n_2} \frac{1}{TH^2} \mathcal{K}(d, n_0, n_1, n_2)$ is non-decreasing in $\mathcal{N}, H_j$, so we can plug in the upper bounds in $\mathcal{N} \ll HL$ and $H_j \ll H$ and simplify the resulting expression to obtain
\[
\begin{aligned}
    \sum_{n_1, n_2 \sim L}
    \sum_{d \mid n_0 n_1 n_2}
    \frac{1}{TH^2} \mathcal{K}(d, n_0, n_1, n_2)
    \ll_\delta 
    x^{O(\delta)}
    \left(1 + \frac{S^{3/4} R^{1/4} n_0^{3/4}}{N^{3/2}} \min\left(1, \frac{\sqrt{H+L}}{H}\right) \right)^\theta
    \\
    \times
    \max\left(H^{1/2} L^{3/2}, L^2\right)
    \left(\frac{\sqrt{RS}}{H} + \frac{S}{H} + \sqrt{\frac{L}{H}}\right).
\end{aligned}
\]
Summing over $n_0$ and plugging in the bounds for $R, S, L$ from \cref{eq:RS-values,eq:L-value}, we get
\[
\begin{aligned}
    \Upsilon_k 
    &:= 
    \sum_{n_0 \ll N} \rho(n_0) \sum_{n_1, n_2 \sim L} \sum_{d \mid n_0 n_1 n_2} \frac{1}{TH^2} \mathcal{K}(d, n_0, n_1, n_2)
    \\
    &\ll_\delta 
    x^{O(\delta)}
    \sum_{n_0 \ll N} 
    \left(1 + \frac{\sqrt{PN} n_0^{1/4}}{\sqrt{k} N^{3/2}} \min\left(1, \frac{\sqrt{H+\frac{N}{kn_0}}}{H}\right) \right)^\theta
    \\
    &\times
    \max\left(H^{1/2} \left(\frac{N}{kn_0}\right)^{3/2}, \left(\frac{N}{kn_0}\right)^2\right)
    \left(\frac{\sqrt{PN}}{\sqrt{k n_0} H} + \sqrt{\frac{N}{kn_0 H}}\right).
\end{aligned}
\]
Using that $H \ll N$, this further yields
\[
\begin{aligned}
    \Upsilon_k 
    &\ll_\delta 
    \frac{x^{O(\delta)}}{k}
    \sum_{n_0 \ll N} 
    \frac{1}{n_0^{2-(\theta/4)}}
    \left(1 + \frac{\sqrt{PN}}{N^{3/2}} \min\left(1, \frac{\sqrt{N}}{H}\right) \right)^\theta
    N^2
    \left(\frac{\sqrt{PN}}{H} + \sqrt{\frac{N}{H}}\right)
    \\
    &\ll_\delta
    \frac{x^{O(\delta)}}{k} 
    \left(1 + \min\left(\frac{\sqrt{P}}{N}, \frac{\sqrt{P}}{\sqrt{N} H}\right) \right)^\theta 
    \left( 
    \frac{\sqrt{P} N^{5/2}}{H} + \frac{N^{5/2}}{\sqrt{H}}
    \right).
\end{aligned}
\]
Since we have $N \le \sqrt{x} \le \sqrt{P}$ and $\sqrt{N}H \le x^{1/4} P x^{-1+\delta} \le x^{1/4 + 3/4 -1 + \delta} \sqrt{P}$ for the ranges in \cref{prop:type-II}.$(i)$, we may ignore the $1$-term in the $\theta$-factor; plugging in \cref{eq:H-value}, we obtain
\[
    \Upsilon_k \ll_\delta 
    \frac{x^{1+O(\delta)} N^{5/2}}{k \sqrt{P}} 
    \min\left(\frac{\sqrt{P}}{N}, \frac{x}{\sqrt{NP}}\right)^\theta,
\]
which improves \cite[(3.7)]{merikoski2023largest}. In light of \cref{eq:sigma-k-cauchy} and $MN = P$, this gives a contribution to $\Sigma_k(M, N)$ of
\[
    \ll_\delta 
    \frac{x^{1/2+O(\delta)}}{k}
    P^{1/4} N^{3/4}
    \min\left(\frac{\sqrt{P}}{N}, \frac{x}{\sqrt{NP}}\right)^{\theta/2},
\]
which is acceptable (i.e., $\ll_\varepsilon x^{1-\delta}/k$) provided that for a large enough absolute constant $K$,
\[
    N \ll_\varepsilon x^{-K\delta} \max\left(x^{2/(3-2\theta)} P^{-(1+\theta)/(3-2\theta)}, x^{2(1-\theta)/(3-\theta)} P^{-(1-\theta)/(3-\theta)} \right).
\]
Choosing $\delta := \varepsilon/K$ and substituting $P = x^\alpha$ completes our proof.

